//! The build-time collector behind the "declare in code" model.
//!
//! A consumer crate's `build.rs` calls [`run`]. It scans the crate's `src/` for
//! `google_font!` / `local_font!` calls (parsed through the same
//! [`proa_fonts_parse`] grammar the macro uses, so ids always agree), vendors
//! each declared font, records the result in `proa-fonts.lock`, and writes a
//! single generated file into `OUT_DIR` that defines one
//! `pub const FONT_<id>: Font` per declaration. The macro expands to a
//! reference to that const, so `cargo build` alone wires everything up.
//!
//! Vendoring is lock-gated: a declaration whose lock entry, vendored files,
//! and (for local sources) source files are intact regenerates from the bytes
//! on disk, touching neither the network nor the vendored files. Only new or
//! changed declarations resolve through the face resolver (reading local
//! files, or fetching Google sources through [`crate::google`] when the
//! default `fetch` feature is enabled). Vendored files no surviving lock
//! entry references are deleted. When any source file fails to parse (a
//! mid-edit save), existing lock entries and vendored files are preserved
//! rather than treated as removed declarations.
//!
//! The lock file always exists after a run, even with zero declarations (a
//! comment-only stub), so a `cargo:rerun-if-changed=proa-fonts.lock`
//! directive is sound from the first build; lock and generated-module writes
//! are skipped when content is unchanged, so the directive cannot loop.
//!
//! Offline behavior: during a `CARGO_NET_OFFLINE=true` build, local sources
//! still vendor (no network involved) and a needed Google fetch fails with an
//! actionable error. [`sync`] with `offline` is stricter: verify-only for
//! every source, performing no writes and failing when the lock or vendored
//! files do not already satisfy the declarations.

use std::collections::{BTreeMap, BTreeSet};
use std::path::{Path, PathBuf};

use proa_fonts::request::{FontRequest, RequestSource};
use proa_fonts::{FontStyle, FontWeight};
use syn::visit::{self, Visit};

use crate::config::{FontsLock, LockEntry, LockFallback, LockFile, LockMetrics};
use crate::error::BuildError;
use crate::google;
use crate::{emit, generate_font, hash, FaceInput, FontSpec, GeneratedFont};

/// The name of the generated file written into `OUT_DIR`. A consumer wires it
/// in with `mod __proa_fonts_generated { include!(concat!(env!("OUT_DIR"), "/proa_fonts.rs")); }`.
pub const GENERATED_FILE: &str = "proa_fonts.rs";

/// The lock file recorded beside the crate's `Cargo.toml`. Commit it together
/// with the vendored files.
pub const LOCK_FILE: &str = "proa-fonts.lock";

/// The comment-only lock written when a crate declares no fonts, so the file
/// always exists for `cargo:rerun-if-changed`.
const EMPTY_LOCK: &str = "\
# @generated by proa_fonts_build. Records vendored font integrity for
# google_font!/local_font! declarations; commit this file.
";

/// Where the collector reads and writes.
pub struct CollectOptions {
    /// Crate root; its `src/` is scanned for font declarations.
    pub crate_root: PathBuf,
    /// Directory the generated `proa_fonts.rs` is written to (usually
    /// `OUT_DIR`). Empty to skip module generation (the CLI `sync` path).
    pub out_dir: PathBuf,
    /// Directory vended, content-hashed files are written to (served as
    /// `/fonts`). Resolved against `crate_root` when relative.
    pub fonts_out_dir: PathBuf,
    /// Root-absolute URL prefix referenced by the generated CSS.
    pub url_prefix: String,
    /// Lock file path. `None` selects `<crate_root>/proa-fonts.lock`.
    pub lock_path: Option<PathBuf>,
}

impl CollectOptions {
    /// The standard `build.rs` configuration: crate root and `OUT_DIR` from
    /// the Cargo build environment, vendored files under `public/fonts`
    /// served at `/fonts`, and the lock beside `Cargo.toml`.
    pub fn from_build_env() -> Result<Self, BuildError> {
        let crate_root: PathBuf = std::env::var_os("CARGO_MANIFEST_DIR")
            .ok_or(BuildError::Environment("CARGO_MANIFEST_DIR"))?
            .into();
        let out_dir: PathBuf = std::env::var_os("OUT_DIR")
            .ok_or(BuildError::Environment("OUT_DIR"))?
            .into();
        Ok(Self {
            crate_root,
            out_dir,
            fonts_out_dir: PathBuf::from("public/fonts"),
            url_prefix: "/fonts".to_string(),
            lock_path: None,
        })
    }

    fn fonts_dir(&self) -> PathBuf {
        if self.fonts_out_dir.is_absolute() {
            self.fonts_out_dir.clone()
        } else {
            self.crate_root.join(&self.fonts_out_dir)
        }
    }

    fn lock_file(&self) -> PathBuf {
        self.lock_path
            .clone()
            .unwrap_or_else(|| self.crate_root.join(LOCK_FILE))
    }
}

/// How a collection is allowed to interact with the world.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum VendorMode {
    /// Resolve, vendor, and write freely.
    Write,
    /// A `CARGO_NET_OFFLINE=true` build: local sources vendor normally, a
    /// needed Google fetch is an error.
    OfflineBuild,
    /// Verify-only: no writes of any kind; any drift between the declarations
    /// and the lock (or vendored files) is an error.
    Verify,
}

/// What a collection produced.
#[derive(Debug, Default)]
pub struct CollectResult {
    /// Path of the generated module file (empty when module generation was
    /// skipped).
    pub module_path: PathBuf,
    /// Const identifiers generated, e.g. `["FONT_9F2C1A3B"]`.
    pub fonts: Vec<String>,
    /// Per-declaration vendoring reports.
    pub reports: Vec<FontReport>,
    /// Vended filenames deleted because no surviving declaration references
    /// them.
    pub removed: Vec<String>,
    /// Source files skipped because they failed to parse. When non-empty,
    /// existing lock entries were preserved instead of cleaned up.
    pub skipped_sources: Vec<PathBuf>,
    /// Lock keys carried forward unverified because their source file may be
    /// among the skipped ones.
    pub preserved: Vec<String>,
}

/// How one declaration was satisfied.
#[derive(Debug, Clone)]
pub struct FontReport {
    /// Lock key, e.g. `"geist_9f2c1a3b"`.
    pub key: String,
    pub family: String,
    pub const_ident: String,
    /// Number of vendored files backing this font.
    pub files: usize,
    /// True when the resolver ran (fetch or local read); false when the lock
    /// and vendored files satisfied the declaration untouched.
    pub refreshed: bool,
    /// True when the declaration was unchanged but its vendored files were
    /// missing or failed integrity checks, forcing the refresh.
    pub repaired: bool,
}

/// Resolves a declaration into the face bytes to vend.
pub type FaceResolver<'a> = dyn Fn(&FontRequest) -> Result<Vec<FaceInput>, BuildError> + 'a;

/// Scan, vendor, and generate with the stock resolver: local files are read
/// from the crate; Google sources are fetched when the `fetch` feature is on
/// (the default). Honors `CARGO_NET_OFFLINE=true`.
pub fn run(opts: &CollectOptions) -> Result<CollectResult, BuildError> {
    run_with_resolver(opts, &stock_resolver(opts.crate_root.clone()))
}

/// Scan, resolve each new or changed declaration with `resolver`, vendor, and
/// generate.
pub fn run_with_resolver(
    opts: &CollectOptions,
    resolver: &FaceResolver<'_>,
) -> Result<CollectResult, BuildError> {
    let mode = if cargo_net_offline() {
        VendorMode::OfflineBuild
    } else {
        VendorMode::Write
    };
    let (generated, mut result) = vendor(opts, resolver, mode)?;

    if !opts.out_dir.as_os_str().is_empty() {
        std::fs::create_dir_all(&opts.out_dir)?;
        let file = if generated.is_empty() {
            "// @generated by proa_fonts_build - no font declarations.\n".to_string()
        } else {
            let mut file = emit::file_header();
            for (req, font) in &generated {
                file.push_str(&emit_item(req, font));
                file.push('\n');
            }
            file
        };
        result.module_path = opts.out_dir.join(GENERATED_FILE);
        write_if_changed(&result.module_path, file.as_bytes())?;
    }
    Ok(result)
}

/// Vendor and lock without emitting the generated module: the `proa font
/// sync` path. With `offline` (or `CARGO_NET_OFFLINE=true`), verify-only: no
/// writes, and any drift is an error.
pub fn sync(opts: &CollectOptions, offline: bool) -> Result<CollectResult, BuildError> {
    let mode = if offline || cargo_net_offline() {
        VendorMode::Verify
    } else {
        VendorMode::Write
    };
    let (_, result) = vendor(opts, &stock_resolver(opts.crate_root.clone()), mode)?;
    Ok(result)
}

/// The stock source resolver: local files from the crate root; Google through
/// the `fetch` feature.
fn stock_resolver(
    crate_root: PathBuf,
) -> impl Fn(&FontRequest) -> Result<Vec<FaceInput>, BuildError> {
    move |req: &FontRequest| match req.source {
        RequestSource::Local => resolve_local(&crate_root, req),
        RequestSource::Google => resolve_google(req),
    }
}

#[cfg(feature = "fetch")]
fn resolve_google(req: &FontRequest) -> Result<Vec<FaceInput>, BuildError> {
    google::resolve(req)
}

#[cfg(not(feature = "fetch"))]
fn resolve_google(_req: &FontRequest) -> Result<Vec<FaceInput>, BuildError> {
    Err(BuildError::InvalidFont(
        "google_font! needs the `fetch` feature of proa_fonts_build (on by default), \
         or a fetcher injected via `run_with_resolver`",
    ))
}

fn cargo_net_offline() -> bool {
    std::env::var("CARGO_NET_OFFLINE").is_ok_and(|v| v == "true")
}

// ---------------------------------------------------------------------------
// vendoring core
// ---------------------------------------------------------------------------

type GeneratedSet = Vec<(FontRequest, GeneratedFont)>;

fn vendor(
    opts: &CollectOptions,
    resolver: &FaceResolver<'_>,
    mode: VendorMode,
) -> Result<(GeneratedSet, CollectResult), BuildError> {
    let scan = scan_requests(&opts.crate_root.join("src"))?;
    if mode == VendorMode::Verify && !scan.skipped.is_empty() {
        return Err(BuildError::Stale(format!(
            "{} source file(s) under src/ could not be parsed, so the declarations \
             cannot be verified",
            scan.skipped.len()
        )));
    }
    let lock_path = opts.lock_file();
    let previous = load_lock(&lock_path)?;
    let fonts_dir = opts.fonts_dir();

    let mut next = FontsLock::default();
    let mut generated = GeneratedSet::new();
    let mut pending_files: Vec<(String, Vec<u8>)> = Vec::new();
    let mut result = CollectResult {
        skipped_sources: scan.skipped.clone(),
        ..CollectResult::default()
    };

    // Deduplicate identical declarations by id; distinct declarations that
    // collide on the truncated id are an error rather than a silent alias.
    let mut seen: BTreeMap<String, String> = BTreeMap::new();
    for req in &scan.requests {
        let id = req.request_id();
        let canonical = req.canonical_key();
        match seen.get(&id) {
            Some(existing) if *existing == canonical => continue,
            Some(existing) => {
                return Err(BuildError::IdCollision(
                    display_key(existing),
                    req.family.clone(),
                ))
            }
            None => {
                seen.insert(id.clone(), canonical);
            }
        }
        let key = format!("{}_{id}", crate::family_slug(&req.family, '_'));

        let satisfied = previous
            .fonts
            .get(&key)
            .filter(|entry| entry.request_id == id)
            .and_then(|entry| regenerate_from_lock(opts, &fonts_dir, req, entry));

        let (font, refreshed, repaired) = match satisfied {
            Some(font) => (font, false, false),
            None => {
                let repaired = previous
                    .fonts
                    .get(&key)
                    .is_some_and(|entry| entry.request_id == id);
                match (mode, req.source) {
                    (VendorMode::Verify, _) => {
                        return Err(BuildError::Stale(format!(
                            "font `{}` is not satisfied by the lock and vendored files",
                            req.family
                        )));
                    }
                    (VendorMode::OfflineBuild, RequestSource::Google) => {
                        return Err(BuildError::Offline(req.family.clone()));
                    }
                    _ => {}
                }
                let faces = resolver(req)?;
                if faces.is_empty() {
                    return Err(BuildError::NoFaces);
                }
                let font = generate_font(&font_spec(opts, req, faces))?;
                for face in &font.faces {
                    if !is_plain_filename(&face.filename) {
                        return Err(BuildError::InvalidFont(
                            "resolved font filename escapes the fonts directory",
                        ));
                    }
                    pending_files.push((face.filename.clone(), face.bytes.clone()));
                }
                (font, true, repaired)
            }
        };

        let entry = lock_entry(req, &font);
        result.reports.push(FontReport {
            key: key.clone(),
            family: req.family.clone(),
            const_ident: req.const_ident(),
            files: entry.files.len(),
            refreshed,
            repaired,
        });
        result.fonts.push(req.const_ident());
        next.fonts.insert(key, entry);
        generated.push((req.clone(), font));
    }

    // A source file that failed to parse may hold declarations we cannot see.
    // Preserve its lock entries and vendored files instead of treating them
    // as removed; the compiler reports the syntax error right after.
    if !scan.skipped.is_empty() {
        for (key, entry) in &previous.fonts {
            if !next.fonts.contains_key(key) {
                next.fonts.insert(key.clone(), entry.clone());
                result.preserved.push(key.clone());
            }
        }
    }

    if mode == VendorMode::Verify {
        if next != previous {
            return Err(BuildError::Stale(
                "the declarations and proa-fonts.lock disagree".to_string(),
            ));
        }
        return Ok((generated, result));
    }

    // Write phase: vendored files first, then removals, then the lock.
    if !pending_files.is_empty() {
        std::fs::create_dir_all(&fonts_dir)?;
        for (filename, bytes) in &pending_files {
            write_if_changed(&fonts_dir.join(filename), bytes)?;
        }
    }

    // Drop vendored files no surviving lock entry references (files of
    // removed declarations, and files orphaned by a refreshed entry).
    let surviving: BTreeSet<&str> = next
        .fonts
        .values()
        .flat_map(|e| e.files.iter().map(|f| f.filename.as_str()))
        .collect();
    for entry in previous.fonts.values() {
        for file in &entry.files {
            if surviving.contains(file.filename.as_str()) || !is_plain_filename(&file.filename) {
                continue;
            }
            let path = fonts_dir.join(&file.filename);
            if path.exists() {
                std::fs::remove_file(&path)?;
                result.removed.push(file.filename.clone());
            }
        }
    }
    result.removed.sort();
    result.removed.dedup();

    let serialized = if next.fonts.is_empty() {
        EMPTY_LOCK.to_string()
    } else {
        toml::to_string_pretty(&next).map_err(|e| BuildError::Lock(e.to_string()))?
    };
    write_if_changed(&lock_path, serialized.as_bytes())?;

    Ok((generated, result))
}

/// The family half of an id-collision message, recovered from a canonical key.
fn display_key(canonical: &str) -> String {
    canonical
        .split('\u{1f}')
        .nth(1)
        .unwrap_or(canonical)
        .to_string()
}

/// Try to satisfy a declaration from the lock and the bytes on disk. Returns
/// the regenerated font, or `None` when anything is missing, altered, or
/// recorded without v2 face metadata. For local sources the declared source
/// files must also still match the vendored bytes.
fn regenerate_from_lock(
    opts: &CollectOptions,
    fonts_dir: &Path,
    req: &FontRequest,
    entry: &LockEntry,
) -> Option<GeneratedFont> {
    if req.source == RequestSource::Local {
        if req.files.len() != entry.files.len() {
            return None;
        }
        for (rel, locked) in req.files.iter().zip(&entry.files) {
            let bytes = std::fs::read(opts.crate_root.join(rel)).ok()?;
            if hash::sha256_hex(&bytes) != locked.sha256 {
                return None;
            }
        }
    }

    let mut faces = Vec::with_capacity(entry.files.len());
    for file in &entry.files {
        if file.stem.is_empty() || file.weight.is_empty() || file.style.is_empty() {
            return None; // pre-metadata entry: re-resolve
        }
        if !is_plain_filename(&file.filename) {
            return None;
        }
        let bytes = std::fs::read(fonts_dir.join(&file.filename)).ok()?;
        if bytes.len() as u64 != file.bytes || hash::sha256_hex(&bytes) != file.sha256 {
            return None;
        }
        faces.push(FaceInput {
            bytes,
            weight: parse_weight_field(&file.weight)?,
            style: parse_style_field(&file.style)?,
            display: crate::parse_display(Some(&file.display)),
            unicode_range: file.unicode_range.clone(),
            preload: file.preload,
            stem: file.stem.clone(),
        });
    }
    if faces.is_empty() {
        return None;
    }

    let font = generate_font(&font_spec(opts, req, faces)).ok()?;

    // The regenerated filenames must be exactly the locked ones; a mismatch
    // means the pipeline changed and the entry is stale.
    let regenerated: Vec<&str> = font.faces.iter().map(|f| f.filename.as_str()).collect();
    let locked: Vec<&str> = entry.files.iter().map(|f| f.filename.as_str()).collect();
    (regenerated == locked).then_some(font)
}

fn font_spec(opts: &CollectOptions, req: &FontRequest, faces: Vec<FaceInput>) -> FontSpec {
    FontSpec {
        family: req.family.clone(),
        generic: req.generic.into(),
        fallback_local: req.fallback_local.clone(),
        extra_stack: req.extra_stack.clone(),
        variable: req.variable.clone(),
        url_prefix: opts.url_prefix.clone(),
        faces,
    }
}

fn lock_entry(req: &FontRequest, font: &GeneratedFont) -> LockEntry {
    LockEntry {
        family: font.family.clone(),
        request_id: req.request_id(),
        const_name: req.const_ident(),
        class_name: font.class_name.clone(),
        css_variable: font.variable.clone(),
        family_stack: font.family_stack.clone(),
        files: font
            .faces
            .iter()
            .map(|f| LockFile {
                filename: f.filename.clone(),
                url: f.url.clone(),
                sha256: f.sha256_hex.clone(),
                bytes: f.bytes.len() as u64,
                stem: f.filename.split('.').next().unwrap_or_default().to_string(),
                weight: format_weight_field(f.weight),
                style: google::style_label(f.style).to_string(),
                display: display_field(f.display),
                unicode_range: f.unicode_range.clone(),
                preload: f.preload,
            })
            .collect(),
        metrics: LockMetrics {
            units_per_em: font.metrics.units_per_em,
            ascent: font.metrics.ascent,
            descent: font.metrics.descent,
            line_gap: font.metrics.line_gap,
            x_width_avg: font.metrics.x_width_avg,
        },
        fallback: LockFallback {
            local: font.fallback.local.clone(),
            ascent_override: font.fallback.ascent_override.clone(),
            descent_override: font.fallback.descent_override.clone(),
            line_gap_override: font.fallback.line_gap_override.clone(),
            size_adjust: font.fallback.size_adjust.clone(),
        },
        license: req.license.clone(),
    }
}

/// `"400"` for fixed weights, `"min..max"` for variable faces.
fn format_weight_field(weight: FontWeight) -> String {
    match weight {
        FontWeight::Fixed(w) => w.to_string(),
        FontWeight::Variable { min, max } => format!("{min}..{max}"),
    }
}

fn parse_weight_field(s: &str) -> Option<FontWeight> {
    if let Some((min, max)) = s.split_once("..") {
        return Some(FontWeight::Variable {
            min: min.parse().ok()?,
            max: max.parse().ok()?,
        });
    }
    s.parse().ok().map(FontWeight::Fixed)
}

fn parse_style_field(s: &str) -> Option<FontStyle> {
    match s {
        "normal" => Some(FontStyle::Normal),
        "italic" => Some(FontStyle::Italic),
        _ => None,
    }
}

fn display_field(display: crate::FontDisplay) -> String {
    match display {
        crate::FontDisplay::Auto => "auto",
        crate::FontDisplay::Block => "block",
        crate::FontDisplay::Fallback => "fallback",
        crate::FontDisplay::Optional => "optional",
        crate::FontDisplay::Swap => "swap",
    }
    .to_string()
}

fn is_plain_filename(name: &str) -> bool {
    !name.is_empty() && !name.contains('/') && !name.contains('\\') && name != "." && name != ".."
}

fn load_lock(path: &Path) -> Result<FontsLock, BuildError> {
    if !path.exists() {
        return Ok(FontsLock::default());
    }
    let text = std::fs::read_to_string(path)?;
    toml::from_str(&text).map_err(|e| BuildError::Lock(format!("{}: {e}", path.display())))
}

fn write_if_changed(path: &Path, content: &[u8]) -> Result<(), BuildError> {
    if let Ok(existing) = std::fs::read(path) {
        if existing == content {
            return Ok(());
        }
    }
    std::fs::write(path, content)?;
    Ok(())
}

fn emit_item(req: &FontRequest, generated: &GeneratedFont) -> String {
    emit::items(&emit::ModuleView {
        const_name: &req.const_ident(),
        family: &generated.family,
        class_name: &generated.class_name,
        variable: &generated.variable,
        family_stack: &generated.family_stack,
        faces: &generated.faces,
        css: &generated.css,
    })
}

/// What a source scan found.
#[derive(Debug, Default)]
pub struct ScanOutcome {
    /// Every parsed `google_font!` / `local_font!` declaration.
    pub requests: Vec<FontRequest>,
    /// Files skipped because they failed to parse as Rust. The compiler
    /// reports the authoritative error for those; the collector treats their
    /// potential declarations as unknown rather than removed.
    pub skipped: Vec<PathBuf>,
}

/// Parse every `google_font!` / `local_font!` call under `src_dir` into a
/// [`FontRequest`]. Individual calls that fail to parse are skipped (the
/// macro emits the authoritative compile error); whole files that fail to
/// parse are reported in [`ScanOutcome::skipped`].
pub fn scan_requests(src_dir: &Path) -> Result<ScanOutcome, BuildError> {
    let mut outcome = ScanOutcome::default();
    let mut collector = Collector::default();
    if !src_dir.exists() {
        return Ok(outcome);
    }
    for entry in walkdir::WalkDir::new(src_dir) {
        let entry = match entry {
            Ok(entry) => entry,
            Err(error) => {
                // An unreadable directory could hide declarations; report it
                // so the caller preserves state instead of cleaning up.
                outcome.skipped.push(
                    error
                        .path()
                        .map_or_else(|| src_dir.to_path_buf(), Path::to_path_buf),
                );
                continue;
            }
        };
        let path = entry.path();
        if path.extension().and_then(|e| e.to_str()) != Some("rs") {
            continue;
        }
        let Ok(text) = std::fs::read_to_string(path) else {
            outcome.skipped.push(path.to_path_buf());
            continue;
        };
        let Ok(file) = syn::parse_file(&text) else {
            outcome.skipped.push(path.to_path_buf());
            continue;
        };
        collector.visit_file(&file);
    }
    outcome.requests = collector.requests;
    Ok(outcome)
}

#[derive(Default)]
struct Collector {
    requests: Vec<FontRequest>,
}

impl<'ast> Visit<'ast> for Collector {
    fn visit_macro(&mut self, mac: &'ast syn::Macro) {
        let name = mac
            .path
            .segments
            .last()
            .map(|s| s.ident.to_string())
            .unwrap_or_default();
        let parsed = match name.as_str() {
            "google_font" => Some(proa_fonts_parse::parse_google_font(mac.tokens.clone())),
            "local_font" => Some(proa_fonts_parse::parse_local_font(mac.tokens.clone())),
            _ => None,
        };
        if let Some(Ok(req)) = parsed {
            self.requests.push(req);
        }
        visit::visit_macro(self, mac);
    }
}

/// Resolve a local declaration into face inputs by reading its files relative
/// to the crate root.
pub fn resolve_local(crate_root: &Path, req: &FontRequest) -> Result<Vec<FaceInput>, BuildError> {
    let default_weight = req.weights.first().copied().unwrap_or(400);
    let display = crate::parse_display(req.display.as_deref());
    let mut faces = Vec::with_capacity(req.files.len());
    for rel in &req.files {
        let path = crate_root.join(rel);
        let bytes = std::fs::read(&path)?;
        let filename = path
            .file_name()
            .and_then(|s| s.to_str())
            .unwrap_or("font")
            .to_string();
        let (weight, style) = infer_weight_style(&filename, req.variable_font, default_weight);
        let stem = sanitize_stem(&filename);
        // An explicit preload list matches against the stem; the default is
        // the upright faces (italics are rarely above the fold).
        let preload = if req.preload.is_empty() {
            style == FontStyle::Normal
        } else {
            req.preload.iter().any(|p| stem.contains(p.as_str()))
        };
        faces.push(FaceInput {
            bytes,
            weight,
            style,
            display,
            unicode_range: None,
            preload,
            stem,
        });
    }
    Ok(faces)
}

fn infer_weight_style(
    filename: &str,
    variable_font: bool,
    default_weight: u16,
) -> (FontWeight, FontStyle) {
    let lower = filename.to_ascii_lowercase();
    let style = if lower.contains("italic") || lower.contains("oblique") {
        FontStyle::Italic
    } else {
        FontStyle::Normal
    };
    let weight = if variable_font {
        FontWeight::Variable { min: 100, max: 900 }
    } else {
        FontWeight::Fixed(scan_weight(&lower).unwrap_or(default_weight))
    };
    (weight, style)
}

fn scan_weight(s: &str) -> Option<u16> {
    let bytes = s.as_bytes();
    let mut i = 0;
    while i + 3 <= bytes.len() {
        let is_boundary_before = i == 0 || !bytes[i - 1].is_ascii_digit();
        let is_boundary_after = i + 3 >= bytes.len() || !bytes[i + 3].is_ascii_digit();
        if bytes[i].is_ascii_digit()
            && bytes[i + 1].is_ascii_digit()
            && bytes[i + 2].is_ascii_digit()
            && is_boundary_before
            && is_boundary_after
        {
            if let Ok(w) = s[i..i + 3].parse::<u16>() {
                if (100..=900).contains(&w) && w % 100 == 0 {
                    return Some(w);
                }
            }
        }
        i += 1;
    }
    None
}

fn sanitize_stem(filename: &str) -> String {
    let base = filename.rsplit_once('.').map_or(filename, |(b, _)| b);
    let mut out = String::new();
    let mut pending = false;
    for c in base.chars() {
        if c.is_ascii_alphanumeric() {
            if pending && !out.is_empty() {
                out.push('-');
            }
            out.push(c.to_ascii_lowercase());
            pending = false;
        } else {
            pending = true;
        }
    }
    out
}

